    "http://localhost:8000/api/v1/tenant/invoices/16/payments" \
    --header "Authorization: Bearer {YOUR_SANCTUM_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"idempotency_key\": \"b\",
    \"amount\": 22,
    \"reference\": \"g\",
    \"notes\": \"z\",
    \"tenders\": [
        {
            \"method\": \"architecto\",
            \"amount\": 22,
            \"reference\": \"g\"
        }
    ]
}"
</code></pre></div>


